-- Merge joins, Memoize and Unique nodes read through cursors, a row at a
-- time. A merge join reads an outer input in index order as it goes and
-- keeps its inner input, sorted or in index order, to mark and restore a
-- position in it; it returns the unmatched rows of a side it fills. A
-- Memoize returns a repeated key's rows from its cache and, with little
-- work_mem, evicts its least recently used entries. A sorted or hashed
-- Unique makes a semi join's inner relation unique. Each returns its rows
-- in PostgreSQL's order; a scrollable cursor reads the join again.
CREATE TABLE mo (id int, k int, pad text);
CREATE TABLE mi (k int, w text);
INSERT INTO mo SELECT g, g % 400, repeat('o', 40) FROM generate_series(1, 2000) g;
INSERT INTO mi SELECT g % 600, 'w' || g || repeat('i', 200) FROM generate_series(1, 1200) g;
INSERT INTO mi VALUES (NULL, 'null key');
CREATE INDEX mi_k ON mi (k);
ANALYZE mo, mi;
SET enable_hashjoin = off;
SET enable_nestloop = off;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo JOIN mi ON mi.k = mo.k;
DECLARE c CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo JOIN mi ON mi.k = mo.k;
FETCH 7 FROM c;
MOVE 1000 FROM c;
FETCH 5 FROM c;
MOVE ALL FROM c;
COMMIT;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo FULL JOIN mi ON mi.k = mo.k + 300;
DECLARE c CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo FULL JOIN mi ON mi.k = mo.k + 300;
FETCH 6 FROM c;
MOVE 900 FROM c;
FETCH 6 FROM c;
MOVE 1500 FROM c;
FETCH 30 FROM c;
COMMIT;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT mo.id FROM mo WHERE EXISTS (SELECT FROM mi WHERE mi.k = mo.k);
DECLARE c CURSOR FOR SELECT mo.id FROM mo WHERE EXISTS (SELECT FROM mi WHERE mi.k = mo.k);
FETCH 10 FROM c;
MOVE 500 FROM c;
FETCH 10 FROM c;
COMMIT;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT mo.id FROM mo WHERE NOT EXISTS (SELECT FROM mi WHERE mi.k = mo.k + 300);
DECLARE c CURSOR FOR SELECT mo.id FROM mo WHERE NOT EXISTS (SELECT FROM mi WHERE mi.k = mo.k + 300);
FETCH 10 FROM c;
MOVE 200 FROM c;
FETCH 10 FROM c;
COMMIT;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT left(mi.w, 8) FROM mi WHERE NOT EXISTS (SELECT FROM mo WHERE mo.k + 300 = mi.k);
DECLARE c CURSOR FOR SELECT left(mi.w, 8) FROM mi WHERE NOT EXISTS (SELECT FROM mo WHERE mo.k + 300 = mi.k);
FETCH 10 FROM c;
MOVE 300 FROM c;
FETCH 10 FROM c;
COMMIT;
SET work_mem = '64kB';
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT mi.k, mo.id FROM mi JOIN mo ON mo.k = mi.k;
DECLARE c CURSOR FOR SELECT mi.k, mo.id FROM mi JOIN mo ON mo.k = mi.k;
FETCH 8 FROM c;
MOVE 2000 FROM c;
FETCH 8 FROM c;
COMMIT;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c SCROLL CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo LEFT JOIN mi ON mi.k = mo.k + 250;
DECLARE c SCROLL CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo LEFT JOIN mi ON mi.k = mo.k + 250;
FETCH 6 FROM c;
FETCH BACKWARD 3 FROM c;
FETCH ABSOLUTE 2 FROM c;
FETCH ABSOLUTE 3000 FROM c;
FETCH BACKWARD 4 FROM c;
FETCH LAST FROM c;
COMMIT;
RESET enable_nestloop;
SET enable_mergejoin = off;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo JOIN mi ON mi.k = mo.k % 40 WHERE mo.id <= 300;
DECLARE c CURSOR FOR SELECT mo.id, left(mi.w, 8) FROM mo JOIN mi ON mi.k = mo.k % 40 WHERE mo.id <= 300;
FETCH 9 FROM c;
MOVE 200 FROM c;
FETCH 9 FROM c;
MOVE ALL FROM c;
COMMIT;
RESET work_mem;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT left(mi.w, 8) FROM mi WHERE mi.k IN (SELECT mo.k FROM mo WHERE mo.id < 40);
DECLARE c CURSOR FOR SELECT left(mi.w, 8) FROM mi WHERE mi.k IN (SELECT mo.k FROM mo WHERE mo.id < 40);
FETCH 10 FROM c;
MOVE 20 FROM c;
FETCH 10 FROM c;
COMMIT;
SET enable_hashagg = off;
BEGIN;
EXPLAIN (COSTS OFF) DECLARE c CURSOR FOR SELECT left(mi.w, 8) FROM mi WHERE mi.k IN (SELECT mo.k FROM mo WHERE mo.id < 40);
DECLARE c CURSOR FOR SELECT left(mi.w, 8) FROM mi WHERE mi.k IN (SELECT mo.k FROM mo WHERE mo.id < 40);
FETCH 10 FROM c;
MOVE 20 FROM c;
FETCH 10 FROM c;
COMMIT;
RESET enable_hashagg;
RESET enable_mergejoin;
RESET enable_hashjoin;
DROP TABLE mo, mi;
